// Business-owned, pure preference normalization. Native only supplies declared
// legacy bytes and commits valid keys that have no existing personal override.
export function migrate(ctx, event) {
  const input = event || ctx || {}, legacy = input.legacyFiles || {};
  const id = 'quietstart.harmony-star-assistant';
  let row;
  for (const name of ['garden-preferences.json', 'legacy-preferences']) {
    try {
      const parsed = JSON.parse(legacy[name]);
      const candidate = Array.isArray(parsed) ? parsed.find(value => value?.id === id) : parsed;
      if (candidate?.id === id) { row = candidate; break; }
    } catch (_) {}
  }
  if (!row || !Number.isInteger(row.friendSeconds) || row.friendSeconds < 10 || row.friendSeconds > 3600 ||
    ![undefined, 'foreground', 'flexible'].includes(row.runMode) ||
    ![undefined, 'default', 'plant-only', 'steal-only'].includes(row.activityMode) ||
    !['screenSaver', 'autoSteal', 'flexibleAutoSteal', 'autoFertilize', 'showPlots', 'showOrders', 'showAtlas']
      .every(key => row[key] === undefined || typeof row[key] === 'boolean') ||
    ![undefined, 'slow', 'standard', 'fast'].includes(row.screenSaverSpeed) ||
    ![undefined, 'old-first', 'new-first'].includes(row.planting) ||
    ![undefined, 'home-first', 'steal-first'].includes(row.priority)) return { schema: 1, values: {} };
  const autoSteal = row.activityMode === undefined && row.runMode === 'flexible' && typeof row.flexibleAutoSteal === 'boolean' ?
    row.flexibleAutoSteal : row.autoSteal !== false;
  return { schema: 1, values: {
    activityMode: row.activityMode || 'default', friendSeconds: row.friendSeconds, autoSteal,
    screenSaver: row.screenSaver !== false, screenSaverSpeed: ['slow', 'standard', 'fast'].includes(row.screenSaverSpeed) ? row.screenSaverSpeed : 'standard',
    autoFertilize: row.autoFertilize === true,
    planting: ['old-first', 'new-first'].includes(row.planting) ? row.planting : 'old-first',
    priority: ['home-first', 'steal-first'].includes(row.priority) ? row.priority : 'steal-first',
    showPlots: row.showPlots !== false, showOrders: row.showOrders !== false, showAtlas: row.showAtlas !== false
  } };
}
